// roas: [{ prefix:'192.0.2.0', len:24, maxLen:24, originAs:64512 }]
function validateRoute(route, roas) {
  // route = { prefix, len, originAs }
  for (const roa of roas) {
    if (roa.prefix === route.prefix && roa.originAs === route.originAs) {
      return 'valid';
    }
  }
  // No matching ROA found.
  return 'invalid';
}
